classDiagram
  class Repository~T~ {
    <<interface>>
    +find(id: String) T
    +save(entity: T) void
  }
  class OrderRepository {
    -conn: Connection
    +find(id: String) Order
    +save(entity: Order) void
    #flush() void
  }
  class Order {
    +String id
    +Money total
    +List~LineItem~ items
    +addItem(LineItem) void
  }
  class LineItem {
    +String sku
    +int qty
  }
  Repository~T~ <|.. OrderRepository
  OrderRepository ..> Order : manages
  Order "1" *-- "many" LineItem : contains
